def set_cell(grid, row, column, value):
    grid[row][column] = value

def row_totals(grid):
    totals = []
    for row in grid:
        total = 0
        for cell in row:
            total += cell
        totals.append(total)
    return totals

print(row_totals([[1, 2], [3, 4]]))
